const SYSTEM_PROCESS_IGNORE = new Set([
  'system', 'idle', 'svchost.exe', 'explorer.exe', 'steam.exe', 'steamwebhelper.exe',
  'steamservice.exe', 'epicgameslauncher.exe', 'epicwebhelper.exe', 'galaxyclient.exe',
