  const monogram = game?.monogram || computeMonogram(title);
  const shortTitle = title.length > 28 ? `${title.slice(0, 26)}…` : title;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 215" width="460" height="215">
    <defs>
