body {
  background: var(--bg-dark);
  background-image: linear-gradient(90deg, rgba(0, 240, 255, 0.03) 1px, transparent 1px);
  background-size: 64px 64px;
  color: var(--text-main);
  font-family: 'Segoe UI', Inter, system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  padding-bottom: 40px;
}

.app-shell {
  max-width: 1440px;
  margin: 0 auto;
  padding: 20px 24px;
}

.top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border);
  box-shadow: inset 0 -2px 0 0 rgba(252, 238, 9, 0.35);
  margin-bottom: 22px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  font-size: 26px;
  width: 48px;
  height: 48px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  background: linear-gradient(135deg, #fcee09, #ff003c);
  color: #06060a;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 18px rgba(252, 238, 9, 0.35);
  flex-shrink: 0;
}

.brand-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.brand h1 {
  font-size: 1.45rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-family: Consolas, 'Segoe UI', monospace;
}

.accent {
  color: var(--accent-cyan);
}

/* CalVer Header Badge */
.calver-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 6px 100%, 0 calc(100% - 6px));
  font-size: 0.75rem;
  font-weight: 700;
  font-family: Consolas, 'Courier New', monospace;
  background: rgba(252, 238, 9, 0.12);
  color: var(--accent-primary);
  border: 1px solid var(--accent-primary);
  border-left: 3px solid var(--accent-primary);
  cursor: pointer;
  transition: all 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.calver-badge:hover {
  border-color: var(--accent-cyan);
  color: #fff;
}

.btn-calver-action {
  border-color: rgba(255, 0, 60, 0.65);
  background: rgba(255, 0, 60, 0.12);
}

.btn-calver-action:hover:not(:disabled) {
  border-color: var(--accent-crimson);
  background: rgba(255, 0, 60, 0.24);
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.82rem;
  font-family: Consolas, 'Segoe UI', monospace;
  letter-spacing: 0.02em;
  margin-top: 2px;
}

/* Runtime / OS Status Pill in Top Bar */
.runtime-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 4px 12px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 6px 100%, 0 calc(100% - 6px));
  font-size: 0.74rem;
  font-family: Consolas, monospace;
  font-weight: 600;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent-cyan);
  color: var(--text-muted);
}

.runtime-pill.is-native {
  background: rgba(0, 255, 102, 0.08);
  border-color: rgba(0, 255, 102, 0.45);
  box-shadow: 0 0 12px rgba(0, 255, 102, 0.12);
}

.runtime-pill.is-native .runtime-mode {
  color: var(--accent-green);
  font-weight: 700;
}

.runtime-pill.is-web {
  background: rgba(0, 240, 255, 0.08);
  border-color: rgba(0, 240, 255, 0.35);
}

.runtime-pill.is-web .runtime-mode {
  color: var(--accent-cyan);
  font-weight: 700;
}

.runtime-segment {
  color: var(--text-main);
}

.runtime-sep {
  color: var(--text-muted);
  opacity: 0.6;
}

.header-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent-cyan);
  padding: 9px 15px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
  font-size: 0.82rem;
  font-family: Consolas, 'Segoe UI', monospace;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
  transition: all 180ms cubic-bezier(0.16, 1, 0.3, 1);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.btn:disabled {
  opacity: 0.65;
  cursor: wait;
}

.btn-xs {
  padding: 5px 10px;
  font-size: 0.74rem;
  border-radius: 0;
}

.btn-primary {
  background: rgba(252, 238, 9, 0.14);
  color: var(--accent-primary);
  border-color: var(--accent-primary);
  border-left: 3px solid var(--accent-primary);
}

.btn-primary:hover:not(:disabled) {
  background: rgba(252, 238, 9, 0.24);
  box-shadow: 0 0 14px rgba(252, 238, 9, 0.22);
}

.btn-secondary {
  background: var(--bg-card);
  color: var(--text-main);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--bg-card-hover);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.section-header h2 {
  font-size: 1.05rem;
  font-family: Consolas, 'Segoe UI', monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 10px;
}

.os-pill {
  font-size: 0.76rem;
  font-family: Consolas, monospace;
  color: var(--accent-cyan);
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent-cyan);
  padding: 4px 12px;
  border-radius: 0;
}

.hardware-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 14px;
  margin-bottom: 20px;
}

.hw-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent-primary);
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.hw-card:hover {
  border-color: var(--accent-cyan);
  background: var(--bg-card-hover);
}

.hw-label {
  font-size: 0.74rem;
  font-family: Consolas, monospace;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--accent-primary);
  margin-bottom: 4px;
}

.hw-value {
  font-size: 1.02rem;
  font-weight: 700;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hw-meta {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-bottom: 10px;
}

/* Cross-Platform Storage Drive / Linux Mount Pills */
.drive-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 2px;
}

.drive-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  border-radius: 5px;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  font-size: 0.73rem;
  color: var(--text-main);
}

.drive-chip-mount {
  font-family: Consolas, 'Courier New', monospace;
  font-weight: 700;
  color: var(--accent);
}

.drive-chip-free {
  color: var(--text-muted);
}

.score-bar {
  height: 6px;
  background: #1e293b;
  border-radius: 99px;
  overflow: hidden;
}

.score-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #10b981);
  border-radius: 99px;
  transition: width 0.4s ease;
}

.drawer {
  background: var(--bg-card);
  border: 1px solid var(--accent);
  border-radius: 12px;
  padding: 18px;
  margin-bottom: 20px;
}

.drawer h3 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.drawer-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.raw-steam-box {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 16px;
}

.raw-steam-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  font-size: 0.86rem;
  color: var(--accent);
}

#cg-raw-steam-specs {
  width: 100%;
  background: #080b10;
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 10px 12px;
  border-radius: 8px;
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.82rem;
  resize: vertical;
  line-height: 1.45;
}

#cg-raw-steam-specs:focus {
  outline: none;
  border-color: var(--accent);
}

.parse-status {
  font-size: 0.82rem;
  color: var(--green);
  align-self: center;
}

.divider-label {
  display: flex;
  align-items: center;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin: 14px 0;
}

.divider-label::before,
.divider-label::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--border);
}

.divider-label span {
  padding: 0 12px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.form-row label {
  display: flex;
  flex-direction: column;
  font-size: 0.8rem;
  color: var(--text-muted);
  gap: 5px;
}

.form-row input {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 0.88rem;
}

.drawer-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

.hidden {
  display: none !important;
}

.main-split {
  display: grid;
  grid-template-columns: minmax(440px, 500px) 1fr;
  gap: 20px;
  align-items: start;
}

@media (max-width: 980px) {
  .main-split {
    grid-template-columns: 1fr;
  }
}

.game-sidebar {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
}

.sidebar-header h3 {
  font-size: 1rem;
  margin-bottom: 10px;
}

.sidebar-filter-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  background: var(--bg-dark);
  padding: 4px;
  border-radius: 9px;
  border: 1px solid var(--border);
  margin-bottom: 10px;
}

.filter-tab {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  padding: 7px 8px;
  border-radius: 6px;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.filter-tab:hover {
  color: var(--text-main);
}

.filter-tab.active {
  background: rgba(56, 189, 248, 0.14);
  color: var(--accent);
  border-color: rgba(56, 189, 248, 0.4);
}

.tab-count {
  background: rgba(255, 255, 255, 0.08);
  padding: 1px 6px;
  border-radius: 99px;
  font-size: 0.72rem;
}

.sidebar-controls {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
}

#game-search {
  width: 100%;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 9px 12px;
  border-radius: 8px;
  font-size: 0.86rem;
}

.sidebar-select-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.sidebar-select-row select {
  width: 100%;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 7px 9px;
  border-radius: 8px;
  font-size: 0.8rem;
  cursor: pointer;
}

.game-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 680px;
  overflow-y: auto;
}

.game-item {
  padding: 12px;
  border-radius: 10px;
  background: var(--bg-dark);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}

.game-item:hover {
  background: var(--bg-card-hover);
  border-color: var(--border);
}

.game-item.active {
  background: rgba(56, 189, 248, 0.1);
  border-color: var(--accent);
}

.game-item-main {
  flex: 1;
  min-width: 0;
}

.game-item-title {
  font-weight: 600;
  font-size: 0.91rem;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.game-item-badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin-top: 5px;
}

.game-item-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  flex-shrink: 0;
}

.installed-pill {
  font-size: 0.65rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(56, 189, 248, 0.15);
  color: var(--accent);
  border: 1px solid rgba(56, 189, 248, 0.35);
}

/* Cross-Platform Launcher Badges */
.launcher-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.66rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.launcher-steam {
  background: rgba(59, 130, 246, 0.16);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.4);
}

.launcher-epic {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.4);
}

.launcher-heroic-epic {
  background: rgba(6, 182, 212, 0.16);
  color: #22d3ee;
  border: 1px solid rgba(6, 182, 212, 0.45);
}

.launcher-heroic-gog {
  background: rgba(168, 85, 247, 0.16);
  color: #c084fc;
  border: 1px solid rgba(168, 85, 247, 0.45);
}

.launcher-lutris {
  background: rgba(249, 115, 22, 0.16);
  color: #fb923c;
  border: 1px solid rgba(249, 115, 22, 0.45);
}

.launcher-gog {
  background: rgba(139, 92, 246, 0.16);
  color: #a78bfa;
  border: 1px solid rgba(139, 92, 246, 0.45);
}

.launcher-xbox {
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.45);
}

.launcher-standalone {
  background: rgba(148, 163, 184, 0.15);
  color: #cbd5e1;
  border: 1px solid rgba(148, 163, 184, 0.35);
}

/* Proton / Linux Runtime Badges */
.runtime-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.66rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  white-space: nowrap;
}

.runtime-proton {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.4);
}

.runtime-native-linux {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.4);
}

.runtime-wine {
  background: rgba(217, 70, 239, 0.15);
  color: #e879f9;
  border: 1px solid rgba(217, 70, 239, 0.4);
}

/* Open Game Folder Button on Card & Modal */
.btn-open-folder-card {
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: var(--accent);
  font-size: 0.68rem;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.btn-open-folder-card:hover {
  background: rgba(56, 189, 248, 0.2);
  border-color: var(--accent);
}

.game-item-meta {
  font-size: 0.76rem;
  color: var(--text-muted);
  margin-top: 3px;
}

.badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 99px;
  white-space: nowrap;
  text-transform: uppercase;
}

.badge-ultra {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(16, 185, 129, 0.35);
}

.badge-rec {
  background: var(--blue-bg);
  color: var(--blue);
  border: 1px solid rgba(59, 130, 246, 0.35);
}

.badge-min {
  background: var(--amber-bg);
  color: var(--amber);
  border: 1px solid rgba(245, 158, 11, 0.35);
}

.badge-fail {
  background: var(--red-bg);
  color: var(--red);
  border: 1px solid rgba(239, 68, 68, 0.35);
}

.badge-warn {
  background: var(--amber-bg);
  color: var(--amber);
}

.analysis-panel {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 22px;
}

.game-hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 14px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}

.game-hero h2 {
  font-size: 1.45rem;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.game-hero-badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin-top: 6px;
}

.game-hero-meta {
  color: var(--text-muted);
  font-size: 0.86rem;
  margin-top: 5px;
}

.hero-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.export-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.btn-export {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 7px 12px;
  border-radius: 8px;
  font-size: 0.79rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.btn-export:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--bg-card-hover);
}

.btn-open-folder-hero {
  border-color: rgba(56, 189, 248, 0.45);
  color: var(--accent);
}

/* Installed Game Path & Linux/Proton Detail Banner in Analysis Panel */
.installed-detail-strip {
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  margin-bottom: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.82rem;
}

.installed-path-code {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.78rem;
  color: var(--accent);
  background: var(--bg-dark);
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid var(--border);
  word-break: break-all;
}

/* Native Save Confirmation Banner */
.export-save-banner {
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.45);
  color: var(--text-main);
  padding: 10px 14px;
  border-radius: 8px;
  margin-bottom: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.84rem;
}

.export-save-path {
  font-family: Consolas, 'Courier New', monospace;
  font-weight: 700;
  color: var(--green);
  word-break: break-all;
}

.bottleneck-banner {
  background: rgba(56, 189, 248, 0.08);
  border-left: 4px solid var(--accent);
  padding: 12px 16px;
  border-radius: 6px;
  font-size: 0.9rem;
  margin-bottom: 20px;
}

.fps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 22px;
}

.fps-card {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
  text-align: center;
}

.fps-res {
  font-size: 0.78rem;
  color: var(--text-muted);
  font-weight: 600;
}

.fps-val {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--accent);
  margin: 4px 0;
}

.fps-sub {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.panel-subtitle {
  font-size: 1rem;
  font-weight: 700;
  margin: 20px 0 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.settings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
  margin-bottom: 22px;
}

.setting-box {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 11px 14px;
}

.setting-name {
  font-size: 0.74rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.setting-val {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-main);
  margin-top: 2px;
}

/* Per-Setting FPS Gain & VRAM Impact Table */
.impact-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 22px;
  font-size: 0.85rem;
}

.impact-table th,
.impact-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

.impact-table th {
  color: var(--text-muted);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.impact-bar-cell {
  min-width: 150px;
}

.impact-bar-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--green);
  margin-bottom: 4px;
}

.impact-bar-track {
  height: 7px;
  background: #1e293b;
  border-radius: 99px;
  overflow: hidden;
}

.impact-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #10b981, #38bdf8);
  border-radius: 99px;
}

.vram-chip {
  display: inline-block;
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.3);
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.76rem;
  font-weight: 600;
  white-space: nowrap;
}

.visual-cost-chip {
  display: inline-block;
  background: rgba(148, 163, 184, 0.12);
  color: var(--text-muted);
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 0.75rem;
  white-space: nowrap;
}

.impact-note {
  color: var(--text-muted);
  font-size: 0.79rem;
  line-height: 1.35;
}

.comp-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 18px;
  font-size: 0.88rem;
}

.comp-table th,
.comp-table td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}

.comp-table th {
  color: var(--text-muted);
  font-size: 0.78rem;
  text-transform: uppercase;
}

.tips-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tips-list li {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 0.88rem;
}

.empty-state {
  padding: 40px 20px;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.92rem;
}

.empty-state-sm {
  padding: 12px 14px;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.8rem;
  background: var(--bg-dark);
  border: 1px dashed var(--border);
  border-radius: 8px;
}

/* CalVer Patch & Native Installer Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: rgba(5, 8, 15, 0.78);
  backdrop-filter: blur(5px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.modal-card {
  width: 100%;
  max-width: 860px;
  max-height: 90vh;
  overflow-y: auto;
  background: var(--bg-card);
  border: 1px solid rgba(56, 189, 248, 0.45);
  border-radius: 14px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.75);
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 18px 22px;
  border-bottom: 1px solid var(--border);
}

.modal-header h2 {
  font-size: 1.2rem;
  font-weight: 700;
}

.modal-subtitle {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.btn-modal-close {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-muted);
  width: 32px;
  height: 32px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.95rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn-modal-close:hover {
  border-color: var(--red);
  color: var(--red);
}

.modal-body {
  padding: 18px 22px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.modal-section {
  background: rgba(10, 14, 23, 0.65);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 15px 16px;
}

.modal-section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 12px;
}

.modal-section-title {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.modal-section-header .modal-section-title {
  margin-bottom: 0;
}

.modal-section-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.calver-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 10px;
}

@media (max-width: 680px) {
  .calver-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.calver-stat-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
}

.calver-stat-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.calver-stat-value {
  font-size: 1.05rem;
  font-weight: 800;
  font-family: Consolas, 'Courier New', monospace;
  margin-top: 2px;
}

.calver-notes-strip {
  font-size: 0.8rem;
  color: var(--text-muted);
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 7px 11px;
}

.patch-op-banner {
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.45);
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 0.81rem;
  margin-bottom: 12px;
}

.patch-subsection-label {
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--text-muted);
  margin-bottom: 7px;
}

.patch-list,
.patch-history-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
}

.patch-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.patch-item-title {
  font-size: 0.86rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.patch-item-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.sha256-pill {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.68rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  background: rgba(16, 185, 129, 0.14);
  color: var(--green);
  border: 1px solid rgba(16, 185, 129, 0.38);
}

.patch-create-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 11px 12px;
}

.patch-create-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.patch-create-row input {
  flex: 1;
  min-width: 220px;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 8px 11px;
  border-radius: 6px;
  font-size: 0.83rem;
}

.installer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 10px;
}

.installer-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
}

.installer-card-title {
  font-size: 0.86rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.installer-card-path {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.74rem;
  color: var(--accent);
  word-break: break-all;
}

.installer-card-meta {
  font-size: 0.74rem;
  color: var(--text-muted);
}

/* Toast Notifications */
.toast-container {
  position: fixed;
  bottom: 22px;
  right: 22px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 440px;
  pointer-events: none;
}

.toast {
  pointer-events: auto;
  background: #131b2e;
  border: 1px solid var(--accent);
  color: var(--text-main);
  padding: 12px 16px;
  border-radius: 10px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.55);
  font-size: 0.84rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  animation: toastSlideIn 0.2s ease-out;
}

.toast-success {
  border-color: var(--green);
  border-left: 4px solid var(--green);
}

.toast-info {
  border-color: var(--accent);
  border-left: 4px solid var(--accent);
}

.toast-warn {
  border-color: var(--amber);
  border-left: 4px solid var(--amber);
}

.toast-error {
  border-color: var(--red);
  border-left: 4px solid var(--red);
}

@keyframes toastSlideIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Primary Display / Monitor Telemetry Card */
.hw-card-display {
  border-color: rgba(56, 189, 248, 0.35);
}

.hw-label-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.hw-label-row .hw-label {
  margin-bottom: 0;
}

.probe-badge {
  font-size: 0.63rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 99px;
  background: rgba(16, 185, 129, 0.14);
  color: var(--green);
  border: 1px solid rgba(16, 185, 129, 0.4);
  white-space: nowrap;
}

.hw-display-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 4px 0 6px;
}

.display-spec-pill {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 5px;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
}

.display-hz-pill {
  color: var(--accent);
  border-color: rgba(56, 189, 248, 0.45);
  background: rgba(56, 189, 248, 0.1);
}

.form-row select {
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 0.88rem;
  cursor: pointer;
}

/* 4-Mode Screen-Aware Optimization Selector */
.opt-mode-bar {
  background: rgba(10, 14, 23, 0.75);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 16px;
}

.opt-mode-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 10px;
}

.opt-mode-title {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--text-main);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.opt-mode-sub {
  font-size: 0.78rem;
  color: var(--text-muted);
}

.opt-mode-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

@media (max-width: 780px) {
  .opt-mode-tabs {
    grid-template-columns: repeat(2, 1fr);
  }
}

.opt-mode-tab {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 9px 10px;
  cursor: pointer;
  text-align: left;
  color: var(--text-muted);
  transition: all 0.15s ease;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.opt-mode-tab:hover {
  border-color: rgba(56, 189, 248, 0.45);
  color: var(--text-main);
  background: var(--bg-card-hover);
}

.opt-mode-tab.active {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.16), rgba(16, 185, 129, 0.1));
  border-color: var(--accent);
  color: var(--text-main);
  box-shadow: 0 0 14px rgba(56, 189, 248, 0.16);
}

.opt-mode-tab-name {
  font-size: 0.82rem;
  font-weight: 700;
  color: inherit;
}

.opt-mode-tab.active .opt-mode-tab-name {
  color: var(--accent);
}

.opt-mode-tab-desc {
  font-size: 0.71rem;
  color: var(--text-muted);
  line-height: 1.25;
}

/* Screen Target & Refresh Saturation Panel */
.screen-target-panel {
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.9), rgba(19, 24, 34, 0.95));
  border: 1px solid rgba(56, 189, 248, 0.38);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 18px;
}

.screen-target-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 10px;
}

.screen-target-title {
  font-size: 0.92rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.screen-target-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.screen-metric-chip {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.76rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 6px;
  background: var(--bg-dark);
  border: 1px solid var(--border);
  color: var(--text-main);
}

.screen-metric-chip.highlight {
  color: var(--green);
  border-color: rgba(16, 185, 129, 0.45);
  background: rgba(16, 185, 129, 0.1);
}

.screen-saturation-row {
  margin-bottom: 8px;
}

.screen-saturation-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.77rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.screen-saturation-track {
  height: 8px;
  background: #1e293b;
  border-radius: 99px;
  overflow: hidden;
}

.screen-saturation-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #10b981);
  border-radius: 99px;
  transition: width 0.35s ease;
}

.screen-sync-advice {
  font-size: 0.8rem;
  color: var(--text-muted);
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 6px;
  border-top: 1px dashed var(--border);
}

/* ============================================================================
 * Non-Invasive Read-Only Telemetry Badge
 * ========================================================================== */
.non-invasive-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.12);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.45);
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.1);
  cursor: help;
}

/* ============================================================================
 * Sleek Vertical Game List View (.games-list-view & .game-list-row)
 * ========================================================================== */
.games-list-view {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 760px;
  overflow-y: auto;
  padding-right: 4px;
}

.game-list-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--bg-dark);
  border: 1px solid rgba(37, 46, 66, 0.85);
  transition: all 0.16s ease;
}

.game-list-row:hover {
  background: var(--bg-card-hover);
  border-color: rgba(56, 189, 248, 0.45);
  transform: translateY(-1px);
}

.game-list-row.active {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.14), rgba(16, 185, 129, 0.06));
  border-color: var(--accent);
  box-shadow: 0 4px 18px rgba(56, 189, 248, 0.15);
}

.game-list-row.is-playing-now {
  border-color: rgba(16, 185, 129, 0.65);
  box-shadow: 0 0 16px rgba(16, 185, 129, 0.18);
}

.game-row-banner-wrap {
  position: relative;
  width: 140px;
  height: 65px;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
  background: #090d16;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.45);
}

.game-row-banner-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.game-row-monogram {
  position: absolute;
  bottom: 4px;
  left: 4px;
  padding: 1px 6px;
  border-radius: 5px;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  background: rgba(10, 14, 23, 0.85);
  color: #f8fafc;
  border: 1px solid rgba(56, 189, 248, 0.45);
  backdrop-filter: blur(4px);
}

.play-activity-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.67rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

.activity-playing {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.55);
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.25);
}

.activity-recent {
  background: rgba(56, 189, 248, 0.16);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.45);
}

.activity-installed {
  background: rgba(168, 85, 247, 0.16);
  color: #d8b4fe;
  border: 1px solid rgba(168, 85, 247, 0.4);
}

.activity-catalog {
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
  border: 1px solid rgba(148, 163, 184, 0.35);
}

.game-row-fps {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.73rem;
  font-weight: 700;
  color: var(--accent);
  white-space: nowrap;
}

.game-row-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.btn-configure-row {
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.38);
  color: var(--text-main);
  font-size: 0.68rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-configure-row:hover {
  background: var(--accent);
  color: #090d16;
}

/* ============================================================================
 * Hero Game Banner + Logo Header in Recommendation Panel (#analysis-hero-banner)
 * ========================================================================== */
.analysis-hero-banner {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(56, 189, 248, 0.38);
  margin-bottom: 18px;
  padding: 0;
  background: #090d16;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
}

.hero-banner-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.hero-banner-bg-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 25%;
  filter: saturate(1.12) contrast(1.05);
  opacity: 0.42;
  transform: scale(1.02);
}

.hero-banner-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(10, 14, 23, 0.94) 0%,
