        g_app.selectedGameIdx = 0;
    }
    const auto& game = g_app.allGames[g_app.selectedGameIdx];
    g_app.currentAnalysis = GameCheck::analyzeGame(g_app.activeSpecs, game, g_app.activeOptMode);

