        game.genre + " \xE2\x80\xA2 " + game.engine + " (" + std::to_string(game.releaseYear) + ") \xE2\x80\xA2 " + upscalerList +
        (game.supportsRT ? " \xE2\x80\xA2 Ray Tracing" : "")
