    RectF metaBox(rx + 110.0f, ry + 41.0f, rw - 320.0f, 18.0f);
    g.DrawString(wMeta.c_str(), -1, &fontCardSub, metaBox, &ellipsisFmt, &cyanBrush);

    // Play Status Pill
    RectF statusPill(rx + 110.0f, ry + 66.0f, 152.0f, 24.0f);
