                : (comps[c]->passMin ? tr(L"Minimum", L"M\x00EDnimo") : tr(L"Low", L"Bajo"));
            std::wstring wCompHdr = GameCheck::utf8ToWide(comps[c]->name) + L" \x2022 " + statusWord;
